CREATE OR REPLACE PROCEDURE sp(para_Election_Cycle VARCHAR2, para_Registration_integer VARCHAR2, para_Treasurer_Vote NUMBER, para_Advisor NUMBER) IS
    CURSOR ref_cursor1 IS SELECT * FROM "Voting_record" FOR UPDATE;
    CURSOR ref_cursor2 IS SELECT * FROM "Student" FOR UPDATE;
    rec1 ref_cursor1%ROWTYPE;
    rec2 ref_cursor2%ROWTYPE;
BEGIN
    INSERT INTO "Voting_record" ("Election_Cycle") VALUES (para_Election_Cycle);
    OPEN ref_cursor1;
    LOOP
        FETCH ref_cursor1 INTO rec1;-- TODO: Handle each voting record fetched by the second cursor loop: update its registration from the parameters, backfill the treasurer vote when appropriate, and propagate the vote to rows for the matching election cycle.

    END LOOP;
    CLOSE ref_cursor1;
    IF para_Treasurer_Vote > 50 THEN
        DELETE FROM "Voting_record" vr WHERE vr."StuID" IN (SELECT s."StuID" FROM "Student" s WHERE s."Advisor" = para_Advisor);
        OPEN ref_cursor2;
        LOOP
            FETCH ref_cursor2 INTO rec2;
            EXIT WHEN ref_cursor2%NOTFOUND;
            IF rec2."Advisor" = para_Advisor THEN
                DELETE FROM "Student" WHERE CURRENT OF ref_cursor2;
            END IF;
        END LOOP;
        CLOSE ref_cursor2;
    END IF;
END;

