    CURSOR ref_cursor2 IS SELECT * FROM "Student" FOR UPDATE;
    rec1 ref_cursor1%ROWTYPE;
    rec2 ref_cursor2%ROWTYPE;
BEGIN
    INSERT INTO "Voting_record" ("Election_Cycle") VALUES (para_Election_Cycle);
    OPEN ref_cursor1;
    LOOP
        FETCH ref_cursor1 INTO rec1;
        EXIT WHEN ref_cursor1%NOTFOUND;
        UPDATE "Voting_record" vr
        SET vr."Registration_integer" =
                CASE
                    WHEN rec1."Treasurer_Vote" IS NOT NULL
                     AND para_Treasurer_Vote IS NOT NULL
                     AND rec1."Treasurer_Vote" = para_Treasurer_Vote
                    THEN para_Registration_integer || rec1."Election_Cycle" || rec1."Secretary_Vote"
                    ELSE para_Registration_integer || rec1."Election_Cycle"
                END,
            vr."Treasurer_Vote" =
                CASE
                    WHEN rec1."Treasurer_Vote" IS NULL AND para_Treasurer_Vote IS NOT NULL
                    THEN para_Treasurer_Vote
                    ELSE vr."Treasurer_Vote"
                END,
            vr."President_Vote" =
                CASE
                    WHEN (rec1."Election_Cycle" IS NULL AND para_Election_Cycle IS NULL)
                      OR (rec1."Election_Cycle" IS NOT NULL AND para_Election_Cycle IS NOT NULL
                          AND rec1."Election_Cycle" = para_Election_Cycle)
                    THEN para_Treasurer_Vote
                    ELSE vr."President_Vote"
                END
        WHERE CURRENT OF ref_cursor1;

